import heapq

def match(orders):
    buy_heap = []   # max-heap by price (store -price), then by arrival, then id
    sell_heap = []  # min-heap by price, then by arrival, then id
    book = {}       # id -> {'side','price','qty','arrival','active'}
    trades = []
    counter = 0

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['active'] = False
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        arrival = counter
        counter += 1

        remaining = qty

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            # clean top of opp_heap of stale/inactive/exhausted entries
            while opp_heap:
                top = opp_heap[0]
                top_id = top[-1]
                info = book.get(top_id)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(opp_heap)
                    continue
                break

            if not opp_heap:
                break

            top = opp_heap[0]
            top_id = top[-1]
            info = book[top_id]
            top_price = info['price']

            if typ == 'market':
                cross = True
            else:
                if side == 'buy':
                    cross = top_price <= price
                else:
                    cross = top_price >= price

            if not cross:
                break

            trade_qty = min(remaining, info['qty'])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'arrival': arrival,
                'active': True
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        # ioc and market: discard remainder, do nothing further

    return trades

